customers-without-orders/schema.sql:
CREATE TABLE customers (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    customer_id INTEGER REFERENCES customers(id)  -- NULL allowed
);

employees-per-department/schema.sql:
CREATE TABLE department (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE employee (
    id            INTEGER PRIMARY KEY,
    name          TEXT NOT NULL,
    salary        INTEGER,  -- NULL allowed
    department_id INTEGER REFERENCES department(id)  -- NULL allowed
);

monthly-sales-ranking/schema.sql:
CREATE TABLE sales (
    id          INTEGER PRIMARY KEY,
    salesperson TEXT NOT NULL,
    month       DATE NOT NULL,
    amount      REAL  -- NULL allowed
);

orders-gap-analysis/schema.sql:
CREATE TABLE orders (
    id          INTEGER PRIMARY KEY,
    customer_id INTEGER NOT NULL,
    order_date  DATE  -- NULL allowed
);

second-highest-salary/schema.sql:
CREATE TABLE employee (
    id     INTEGER PRIMARY KEY,
    name   TEXT NOT NULL,
    salary INTEGER  -- NULL allowed
);

top-three-per-category/schema.sql:
CREATE TABLE category (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE product (
    id          INTEGER PRIMARY KEY,
    name        TEXT NOT NULL,
    category_id INTEGER NOT NULL REFERENCES category(id)
);

CREATE TABLE sale (
    id         INTEGER PRIMARY KEY,
    product_id INTEGER NOT NULL REFERENCES product(id),
    unit_price REAL NOT NULL,
    quantity   INTEGER NOT NULL
);
